    // outlive the device.
    Device* dev = to_device(hdevice);
    if (Event* last = dev->legacy_take_last_event()) {
        last->wait(VX_TIMEOUT_INFINITE);
        last->release();
    }
    return to_int(vx_device_release(hdevice));
